// ————— Projection —————
// The main map: 128.6–146.0°E, 30.0–45.6°N, x scaled by cos 37.5° — the same
// numbers the outline in journey.jsx was cut with (300 × 339).
export const MAP_PROJECTION = { lon0: 128.6, lat1: 45.6, k: 300 / 17.4 / Math.cos(37.5 * Math.PI / 180), cos: Math.cos(37.5 * Math.PI / 180) };
// The Okinawa inset: 123.6–128.4°E, 24.0–27.0°N at cos 25.5°, 120 wide, placed
// at (INSET.x, INSET.y) in the open sea of the main map.
export const INSET = { x: 8, y: 10, w: 120, h: 83.1, lon0: 123.6, lat1: 27.0, cos: Math.cos(25.5 * Math.PI / 180), s: 27.6982 };
export function project(lat, lon) {
  if (lat < 30) return { x: +(INSET.x + (lon - INSET.lon0) * INSET.cos * INSET.s).toFixed(1), y: +(INSET.y + (INSET.lat1 - lat) * INSET.s).toFixed(1), inset: true };
  const P = MAP_PROJECTION;
  return { x: +((lon - P.lon0) * P.cos * P.k).toFixed(1), y: +((P.lat1 - lat) * P.k).toFixed(1) };
}

const slots = (grid) => grid.join("").replace(/\./g, "").length;

export const LANDMARKS = {};
for (const [n, id, en, jp, kana, pref, lat, lon, size, type, grid, note] of ROWS) {
  const t = TYPES[type];
  if (!t) throw new Error("landmark " + id + ": no type " + type);
  LANDMARKS[id] = {
    n, kind: "landmark", size, type, note: note || "",
    jp: t.jp, kana: t.kana, en: t.en,
    place: { jp, kana, en: `${en} — ${pref}`, pref, ...project(lat, lon) },
    grid: box(grid), prefer: PREFER,
  };
}
export const slotsOf = (id) => slots(LANDMARKS[id].grid);

